package com.sereneflow.timer.platform

import com.sereneflow.timer.model.AppThemeMode

/**
 * The launcher icon is chosen per colour theme in Settings → App icon. The icons are generated by
 * tools/generate_icons.swift; Zen Sage is the default, the others are alternates. AppIconAssetsTest
 * checks that every name below has its iOS icon set and Android launcher alias.
 */
val AppThemeMode.iconId: String
    get() = when (this) {
        AppThemeMode.ZEN_SAGE -> "ZenSage"
        AppThemeMode.OCEAN_MIST -> "OceanMist"
        AppThemeMode.SUNSET_CLAY -> "SunsetClay"
        AppThemeMode.MIDNIGHT_STARLIGHT -> "MidnightStarlight"
    }

/** The iOS alternate icon (AppIcon-<id>.appiconset); null selects the primary icon. */
val AppThemeMode.iosIconName: String?
    get() = if (this == AppThemeMode.ZEN_SAGE) null else "AppIcon-$iconId"

/**
 * The Android `<activity-alias>` in androidApp's manifest that shows this icon in the launcher.
 * The default keeps 1.0's launcher component name, so existing home-screen shortcuts survive.
 */
val AppThemeMode.androidLauncherAlias: String
    get() = if (this == AppThemeMode.ZEN_SAGE) "com.sereneflow.timer.MainActivity"
    else "com.sereneflow.timer.Launcher$iconId"

/**
 * Switches the app's launcher icon. The platform keeps the choice (iOS remembers the alternate
 * icon, Android which launcher alias is enabled), so it is read back from there rather than
 * stored in the preferences, where it could disagree.
 */
expect object AppIconSwitcher {
    val isSupported: Boolean

    /** What the user should know about a change on this platform, or null. */
    val changeNote: String?

    fun current(): AppThemeMode

    /** Switches to [icon], then calls [onDone] with the icon the platform now shows (main thread). */
    fun set(icon: AppThemeMode, onDone: (AppThemeMode) -> Unit)
}
